import {renderLongDashboard,renderLongReports} from './dashboard.js';
import {buildOTReport} from '../../src/domain/reports.mjs';
import { projects as demoProjects, employees as demoEmployees, entries as demoEntries, history as demoHistory } from '../../src/data.js';
import {createImportUI} from './excel-importer.js?v=0.5.1';
import {readImportState,activeImports,saveProject,createProject,saveEmployee} from './database.js';
let projects=[],employees=[],entries=[],history=[];
import {employeeMetrics,dayConflicts} from './ot-calculator.js';
import {createRestoreUI,auditPanel,metricsMarkup} from '../../src/db/data-ui.js';
let dataMode='imported',demoUpload=false,storedSnapshot=null;
const restoreUI=createRestoreUI({download:(...args)=>download(...args),notify:message=>toast(message),onRestored:async()=>{await useImportedData({selectLatest:true});render();}});
async function useImportedData({selectLatest=false}={}){
  const snapshot=await readImportState();const active=activeImports(snapshot);
  storedSnapshot=snapshot;
  employees=snapshot.employees.map(e=>({...e,id:e.employeeId,initials:e.employeeId.slice(0,3),color:'green'}));
  projects=snapshot.projects;
  entries=snapshot.otRecords.filter(r=>r.status==='active').map(r=>({...r,nt:r.ntMinutes/60,nn:r.nnMinutes/60}));
  const activeIds=new Set(active.map(i=>i.id));
  history=snapshot.imports.map(i=>({id:i.id,projectId:i.projectId,filename:i.filename,month:i.month,year:i.year,date:i.importedAt,type:i.mode,count:i.records.length,hasDaily:i.records.some(r=>r.source==='daily'),status:activeIds.has(i.id)?'active':'replaced',actor:'Bạn',events:snapshot.importHistory.filter(e=>e.importId===i.id)}));
  history.push(...snapshot.importHistory.filter(e=>e.action==='CANCEL_IMPORT').map(e=>({id:e.id,projectId:e.projectId,filename:e.filename,month:e.month,year:e.year,date:e.at,type:'cancel',count:0,status:'cancelled',events:[e]})));
  history.sort((a,b)=>b.date.localeCompare(a.date));
  dataMode='imported';
  if(selectLatest){const latest=history.find(h=>h.status==='active');if(latest){state.year=latest.year;state.month=latest.month;}state.project='all';state.unit='all';state.search='';}
}
function useDemoData(){projects=demoProjects;employees=demoEmployees;entries=demoEntries;history=demoHistory;dataMode='demo';}
const excelUI=createImportUI({getProjects:()=>dataMode==='imported'?projects:[],notify:message=>toast(message),onCreateProject:onSelect=>projectForm(undefined,onSelect),onDemo:()=>{useDemoData();demoUpload=true;render();},onSaved:async(saved)=>{await useImportedData();const latest=saved||history.find(h=>h.status==='active');if(latest){state.year=latest.year;state.month=latest.month;}state.project='all';state.unit='all';state.search='';location.hash='/history';render();}});

const paths={home:'<rect x="3" y="3" width="7" height="7" rx="1.4"/><rect x="14" y="3" width="7" height="7" rx="1.4"/><rect x="3" y="14" width="7" height="7" rx="1.4"/><rect x="14" y="14" width="7" height="7" rx="1.4"/>',upload:'<path d="M12 16V3m-4 4 4-4 4 4M4 15v5a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-5"/>',folder:'<path d="M3 7a2 2 0 0 1 2-2h5l2 2h7a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/><circle cx="9" cy="7" r="4"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',alert:'<path d="m10.3 3.8-8.2 14A2 2 0 0 0 3.8 21h16.4a2 2 0 0 0 1.7-3.2l-8.2-14a2 2 0 0 0-3.4 0ZM12 9v4m0 4h.01"/>',history:'<path d="M3 11a9 9 0 1 1 2.6 7.4M3 4v7h7m2-4v5l3 2"/>',report:'<path d="M8 3H5a1 1 0 0 0-1 1v16a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1V8l-5-5H8Zm6 0v6h6M8 16v-3m4 3v-5m4 5v-2"/>',database:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 1.7 3.6 3 8 3s8-1.3 8-3V5M4 12c0 1.7 3.6 3 8 3s8-1.3 8-3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18m-13 4h2m4 0h2"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',download:'<path d="M12 3v13m-4-4 4 4 4-4M4 17v4h16v-4"/>',plus:'<path d="M12 5v14M5 12h14"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',check:'<path d="m5 12 4 4L19 6"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',file:'<path d="M14 2H5a1 1 0 0 0-1 1v18a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1V8ZM14 2v6h6M8 12h8m-8 4h8"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',edit:'<path d="m15 5 4 4M4 20l4-1L20 7a2.8 2.8 0 0 0-4-4L4 15v5Z"/>',trend:'<path d="m3 17 6-6 4 4 8-10m-6 0h6v6"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 3H4a1 1 0 0 0-1 1v16a1 1 0 0 0 1 1h16a1 1 0 0 0 1-1v-6"/>',refresh:'<path d="M20 7a9 9 0 0 0-15-2L2 8m0-6v6h6m-4 9a9 9 0 0 0 15 2l3-3m0 6v-6h-6"/>'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.file}</svg>`;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=value=>new Intl.NumberFormat('vi-VN',{maximumFractionDigits:2}).format(value);
const normalize=value=>value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').toLowerCase();
const nav=[['dashboard','home','Tổng quan'],['upload','upload','Upload OT'],['projects','folder','Dự án'],['employees','users','Nhân sự'],['lookup','search','Tra cứu'],['alerts','alert','Cảnh báo'],['history','history','Lịch sử import'],['reports','report','Báo cáo'],['backup','database','Sao lưu dữ liệu']];
const state={month:11,year:2026,route:'dashboard',search:'',project:'all',unit:'all',alertTab:'month',report:'monthly',uploadStep:1,file:null,filename:'',importMode:'initial',previewImports:[],notice:true};
let toastTimer;
const $=selector=>document.querySelector(selector);
const sum=list=>list.reduce((a,r)=>a+(r.totalMinutes!==undefined?r.totalMinutes/60:r.nt+r.nn),0);
const periodEntries=()=>entries.filter(r=>(!state.month||r.month===state.month)&&r.year===state.year);
const metricRecords=()=>entries.map(r=>({...r,ntMinutes:r.ntMinutes??Math.round((r.nt||0)*60),nnMinutes:r.nnMinutes??Math.round((r.nn||0)*60),totalMinutes:r.totalMinutes??Math.round((r.nt+r.nn)*60)}));
const employeeTotals=()=>{const records=metricRecords();return employees.map(e=>{const metrics=employeeMetrics(records,e.id,state.year,state.month||1);return {...e,month:metrics.hours.month,year:metrics.hours.year,projects:metrics.projectIds,metrics};});};
const projectOptions=(all=true)=>`${all?'<option value="all">Tất cả dự án</option>':''}${projects.map(p=>`<option value="${esc(p.id)}" ${state.project===p.id?'selected':''}>${esc(p.id)} · ${esc(p.name)}</option>`).join('')}`;
const yearOptions=()=>[...new Set([2025,2026,2027,state.year,...entries.map(r=>r.year)])].sort((a,b)=>a-b).map(y=>`<option value="${y}" ${y===state.year?'selected':''}>${y}</option>`).join('');
const reportFilters=(kind='dashboard')=>`<div class="report-filters"><select class="field" data-filter="year" aria-label="Năm báo cáo">${yearOptions()}</select><select class="field" data-filter="month" aria-label="Tháng báo cáo" ${kind==='yearly'?'disabled':''}>${kind==='dashboard'?`<option value="0" ${state.month===0?'selected':''}>Tất cả các tháng</option>`:''}${monthOptions()}</select><select class="field" data-filter="project" aria-label="Dự án báo cáo">${projectOptions()}</select></div>`;
const monthOptions=()=>Array.from({length:12},(_,i)=>`<option value="${i+1}" ${i+1===state.month?'selected':''}>Tháng ${String(i+1).padStart(2,'0')}</option>`).join('');
const periodFilter=()=>`<div class="period-filter"><select class="field" data-filter="month" aria-label="Tháng báo cáo">${monthOptions()}</select><select class="field" data-filter="year" aria-label="Năm báo cáo">${yearOptions()}</select></div>`;
const badge=(label,type='green')=>`<span class="badge badge-${type}"><span class="dot"></span>${esc(label)}</span>`;
const button=(label,ic,action,primary=false)=>`<button class="btn ${primary?'btn-primary':''}" data-action="${action}">${ic?icon(ic):''}${label}</button>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function showModal(title,body,actions=''){const modal=$('#modal');modal.innerHTML=`<div class="modal-header"><h2 id="modal-title">${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Đóng hộp thoại">${icon('close')}</button></div><div class="modal-body">${body}</div>${actions?`<div class="modal-actions">${actions}</div>`:''}`;if(!modal.open)modal.showModal();}
function download(filename,text,type='application/json'){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function renderShell(){
 const title=nav.find(n=>n[0]===state.route)?.[2]||'Tổng quan';
 $('#sidebar').innerHTML=`<a class="brand" href="#/dashboard" aria-label="OT Workspace - Tổng quan"><span class="brand-mark">${icon('clock')}</span><div class="brand-name">OT Workspace<div class="brand-caption">PERSONAL OT MANAGEMENT</div></div></a><div class="nav-label">KHÔNG GIAN LÀM VIỆC</div><nav class="nav-group">${nav.slice(0,6).map(navLink).join('')}<div class="nav-spacer"></div><div class="nav-label">DỮ LIỆU & BÁO CÁO</div>${nav.slice(6).map(navLink).join('')}</nav><div class="sidebar-bottom"><div class="storage-card"><p>${icon('shield')} Dữ liệu của bạn, bạn quản lý</p><span>${dataMode==='demo'?'Bản demo chỉ dùng bộ nhớ tạm.<br>Dữ liệu đã nhập được tách riêng.':'Dữ liệu đã nhập lưu trong IndexedDB.<br>Hãy sao lưu định kỳ.'}</span><a href="#/backup">Tìm hiểu về sao lưu ${icon('arrow')}</a></div><div class="sidebar-version"><span>${dataMode==='demo'?'CHẾ ĐỘ XEM TRƯỚC':'DỮ LIỆU TRÊN TRÌNH DUYỆT'}</span><span>v0.5.1</span></div></div>`;
 $('#topbar').innerHTML=`<div class="topbar-left"><button class="icon-btn mobile-menu" data-action="toggle-menu" aria-label="Mở menu" aria-controls="sidebar" aria-expanded="false">${icon('menu')}</button><div class="breadcrumbs">${icon('home')}<span class="crumb-root">Không gian làm việc</span><span class="crumb-root">/</span><span>${title}</span></div></div><div class="topbar-actions"><select class="field workspace-mode" id="workspace-mode" aria-label="Không gian dữ liệu"><option value="demo" ${dataMode==='demo'?'selected':''}>Dữ liệu demo</option><option value="imported" ${dataMode==='imported'?'selected':''}>Dữ liệu đã nhập</option></select><div class="topbar-date">${icon('calendar')} ${new Intl.DateTimeFormat('vi-VN',{dateStyle:'full',timeZone:'Asia/Bangkok'}).format(new Date())}</div><button class="icon-btn" data-action="notifications" aria-label="Xem cảnh báo">${icon('bell')}<span class="notification-dot"></span></button><div class="topbar-divider"></div><div class="profile"><span class="profile-avatar">DE</span><div class="profile-copy"><strong>Không gian cá nhân</strong><span>${dataMode==='demo'?'Dữ liệu giả lập':'Lưu trên trình duyệt'}</span></div></div></div>`;
}
function navLink([route,ic,label]){return `<a class="nav-link ${state.route===route?'active':''}" href="#/${route}" ${state.route===route?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${route==='alerts'?`<span class="nav-count">${employeeTotals().filter(e=>e.month>40).length}</span>`:''}</a>`;}
function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
function demoNotice(){if(dataMode==='imported')return `<div class="notice"><span><strong>Dữ liệu đã nhập</strong> · Đọc từ IndexedDB trên trình duyệt này. Dữ liệu demo được tách riêng.</span></div>`;return `<div class="notice">${icon('info')}<span><strong>Bạn đang ở chế độ xem trước.</strong> Toàn bộ thông tin là giả lập, chỉ nằm trong bộ nhớ tạm và sẽ đặt lại khi tải lại trang.</span></div>`;}
function person(e){return `<div class="person"><span class="avatar ${e.color}">${esc(e.initials)}</span><div><div class="person-name">${esc(e.name)}</div><div class="person-code">${esc(e.id)}</div></div></div>`;}
function stat(label,value,ic,foot,cls='',unit=''){return `<article class="panel stat ${cls}"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon(ic)}</span></div><div class="stat-value">${fmt(value)}${unit?`<small>${unit}</small>`:''}</div><div class="stat-footer">${foot}</div></article>`;}
const currentReport=(month=state.month)=>buildOTReport({records:metricRecords(),employees,projects,year:state.year,month,projectId:state.project});
function dashboard(){return renderLongDashboard({report:currentReport(),projects,filters:reportFilters(),heading,stat,button,icon});}

function uploadView(){return `${heading('Upload chấm công','Tập trung dữ liệu từ các dự án. Kiểm tra rõ ràng trước khi ghi nhận.')}${demoNotice()}<div class="upload-layout section-space"><section class="panel"><div class="panel-body"><div class="steps">${['Chọn dữ liệu','Kiểm tra & ánh xạ','Xác nhận'].map((s,i)=>`<div class="step ${state.uploadStep>=i+1?'active':''}"><b>${i+1}</b><span>${s}</span></div>`).join('')}</div>${state.uploadStep===1?uploadStepOne():state.uploadStep===2?uploadStepTwo():uploadStepThree()}</div></section><aside class="panel"><div class="panel-body"><h2>Nguyên tắc ghi nhận OT</h2><p class="muted small section-space">Kiểm soát ngay từ dữ liệu đầu vào.</p><div class="rule-list">${[['users','Một cán bộ, một mã duy nhất','Mã cán bộ được dùng để cộng dồn giờ OT trên tất cả dự án.'],['clock','40 giờ/tháng · 200 giờ/năm','Vượt ngưỡng sẽ được cảnh báo, không chặn upload. NT: ngày thường · NN: ngày nghỉ.'],['calendar','Một ngày, một dự án','Cần dữ liệu chi tiết theo ngày để xác minh. File chỉ có tổng tháng chưa đủ điều kiện kiểm tra.'],['file','File bổ sung không trùng cán bộ','Trong cùng dự án/tháng, file bổ sung chỉ chứa cán bộ chưa có ở các file đang hiệu lực.'],['history','Thay thế có lịch sử','Thay thế toàn bộ kỳ gồm file gốc và file bổ sung; phiên bản cũ không được cộng tiếp.']].map(([i,t,p])=>`<div class="rule">${icon(i)}<div><strong>${t}</strong><p>${p}</p></div></div>`).join('')}</div></div></aside></div>`;}
function uploadStepOne(){return `<div class="form-grid"><div class="form-group"><label for="upload-project">Dự án <span>*</span></label><select id="upload-project" class="field">${projectOptions(false)}</select></div><div class="form-group"><label for="upload-year">Năm chấm công <span>*</span></label><select id="upload-year" class="field">${yearOptions()}</select><small>Năm cần được xác nhận trước khi hoàn tất.</small></div></div><input id="excel-file" class="file-input" type="file" accept=".xlsx,.xls"><label for="excel-file" class="dropzone" id="dropzone"><span class="upload-symbol">${icon('upload')}</span><h3><strong>Chọn file Excel</strong> hoặc kéo thả vào đây</h3><p>Định dạng .xlsx, .xls · Tối đa 10 MB<br>Bản giao diện chỉ nhận tên file, chưa phân tích nội dung.</p></label>${state.filename?`<div class="file-summary">${icon('file')}<div><strong>${esc(state.filename)}</strong><p>Đã chọn file · Chưa đọc nội dung</p></div><button class="icon-btn" data-action="clear-file" aria-label="Bỏ file đã chọn">${icon('close')}</button></div>`:''}<button class="btn-link" data-action="use-demo">${icon('file')} Thử ngay với bộ dữ liệu giả lập</button><div class="section-space"><div class="form-group"><label>Hình thức nhập dữ liệu</label><div class="selection-cards">${[['initial','Nhập mới','Tạo dữ liệu cho kỳ mới'],['supplement','Bổ sung','Chỉ thêm cán bộ chưa có'],['replace','Thay thế kỳ','Thay toàn bộ dữ liệu của kỳ']].map(([v,t,s])=>`<label class="radio-card"><input type="radio" name="import-mode" value="${v}" ${state.importMode===v?'checked':''}><strong>${t}</strong><br><span class="muted">${s}</span></label>`).join('')}</div></div></div><div class="form-actions"><span class="small muted">${icon('shield')} Không tải file lên máy chủ</span>${button('Xem trước mô phỏng','arrow','upload-next',true)}</div>`;}
function uploadStepTwo(){const supplement=state.importMode==='supplement';return `<div class="notice notice-warning">${icon('info')}<span>Đây là kết quả <strong>mô phỏng từ dữ liệu DEMO</strong>, không phải nội dung file bạn chọn. Tháng 11 chỉ là kỳ minh họa.</span></div><div class="form-grid section-space"><div class="form-group"><label for="mapping-sheet">Sheet minh họa</label><select class="field" id="mapping-sheet"><option>DEMO_ChamCong</option></select></div><div class="form-group"><label for="mapping-month">Tháng chấm công</label><select class="field" id="mapping-month">${monthOptions()}</select></div></div><h3 class="section-space subsection">Ánh xạ cột mẫu</h3><div class="form-grid">${[['Họ và tên','Họ tên'],['Mã cán bộ','Mã CB'],['Đơn vị','Phòng ban'],['Giờ NT','OT ngày thường'],['Giờ NN','OT ngày nghỉ'],['Tổng số giờ','Tổng OT']].map(([label,value],i)=>`<div class="form-group"><label for="mapping-${i}">${label}</label><select class="field" id="mapping-${i}"><option>${value}</option></select></div>`).join('')}</div><div class="notice section-space">${icon('check')}<span>Mẫu sử dụng giờ thập phân. Tổng OT = Giờ NT + Giờ NN.</span></div><div class="form-actions">${button('Quay lại','','upload-back')}${button('Kiểm tra dữ liệu mẫu','arrow','upload-review',true)}</div>`;}
function uploadStepThree(){const duplicate=state.importMode==='supplement';const existing=entries.some(r=>r.projectId===state.project&&r.year===state.year&&r.month===state.month);const blocked=duplicate||(state.importMode==='initial'&&existing);return `<div class="file-summary">${icon('file')}<div><strong>${esc(state.filename)}</strong><p>${esc(state.project)} · Tháng ${state.month}/${state.year} · ${state.importMode==='replace'?'Thay thế toàn bộ kỳ':duplicate?'Bổ sung cán bộ':'Nhập mới'}</p></div>${badge('Mô phỏng','blue')}</div><div class="mini-stats"><div class="mini-stat"><p>Dòng dữ liệu mẫu</p><strong>3</strong></div><div class="mini-stat"><p>Tổng OT mẫu</p><strong>93 <small>giờ</small></strong></div><div class="mini-stat"><p>Trùng cán bộ trong kỳ</p><strong>${duplicate?'2':'0'}</strong></div></div><div class="table-wrap"><table><thead><tr><th>MÃ CÁN BỘ</th><th>NT</th><th>NN</th><th>TỔNG</th></tr></thead><tbody>${[['DEMO001',22,8],['DEMO002',24,9],['DEMO049',20,10]].map(([id,nt,nn])=>`<tr><td>${id}</td><td>${nt}h</td><td>${nn}h</td><td>${nt+nn}h</td></tr>`).join('')}</tbody></table></div><div class="notice notice-warning section-space">${icon('alert')}<span>${duplicate?'<strong>Không thể bổ sung mẫu này.</strong> DEMO001 và DEMO002 được giả lập là đã có trong kỳ. Cần loại các cán bộ trùng trước khi nhập.':state.importMode==='initial'&&existing?'<strong>Kỳ này đã có dữ liệu mẫu.</strong> Quay lại chọn thay thế toàn bộ kỳ hoặc bổ sung.':'Không có dữ liệu theo ngày: <strong>chưa xác minh</strong> một cán bộ có khai cùng ngày ở hai dự án hay không.'}</span></div>${state.importMode==='replace'?'<div class="help-box">Trong hệ thống chính, thao tác này thay toàn bộ file có hiệu lực của dự án/kỳ đã chọn. Ở bản xem trước, chỉ thêm một hoạt động mô phỏng; tổng OT giữ nguyên.</div>':''}<label class="check-line"><input type="checkbox" id="confirm-year">Tôi xác nhận kỳ tháng ${state.month}/${state.year} và hiểu đây chỉ là thao tác mô phỏng, không lưu dữ liệu chính.</label><div class="form-actions">${button('Quay lại','','upload-back')}<button class="btn btn-primary" data-action="confirm-import" ${blocked?'disabled':''}>${icon('check')} Hoàn tất mô phỏng</button></div>`;}
function projectsView(){return `${heading('Quản lý dự án','Theo dõi các không gian dự án và dữ liệu chấm công của từng kỳ.',button('Thêm dự án','plus','add-project',true))}${demoNotice()}<div class="result-count">${projects.length} dự án trong không gian trải nghiệm · Tháng ${state.month}/${state.year}</div><div class="project-grid">${projects.map(p=>{const rs=periodEntries().filter(r=>r.projectId===p.id);return `<article class="panel project-card"><div class="project-top"><span class="project-logo ${p.color}">${esc(p.id)}</span>${badge(p.status==='active'?'Đang hoạt động':'Ngừng hoạt động',p.status==='active'?'green':'neutral')}</div><h2>${esc(p.name)}</h2><p class="project-description">${esc(p.description)}</p><div class="project-metrics"><div><strong>${new Set(rs.map(r=>r.employeeId)).size}</strong><span>Cán bộ trong tháng</span></div><div><strong>${fmt(sum(rs))}<span> h</span></strong><span>Tổng giờ OT tháng</span></div></div><div class="project-owner"><span class="muted">${esc(p.manager)}</span><button class="btn-link" data-action="edit-project" data-id="${esc(p.id)}">Chỉnh sửa ${icon('edit')}</button></div></article>`;}).join('')}</div>`;}
function filterEmployees(){return employeeTotals().filter(e=>normalize(`${e.name} ${e.id} ${e.unit}`).includes(normalize(state.search))&&(state.unit==='all'||e.unit===state.unit)&&(state.project==='all'||e.projects.includes(state.project)));}
function employeeTable(list,lookup=false){return `<div class="table-wrap"><table><thead><tr><th>CÁN BỘ</th><th>ĐƠN VỊ</th><th>DỰ ÁN TRONG THÁNG</th><th>OT THÁNG</th><th>OT NĂM</th><th>CÒN LẠI THÁNG</th><th>CÒN LẠI NĂM</th><th>VƯỢT THÁNG</th><th>VƯỢT NĂM</th><th></th></tr></thead><tbody>${list.map(e=>`<tr><td>${person(e)}</td><td>${esc(e.unit)}</td><td>${e.projects.map(id=>badge(id,'neutral')).join(' ')||'—'}</td><td><strong>${fmt(e.month)}</strong> <span class="muted">giờ</span>${e.month>40?' '+badge('Vượt 40h','orange'):''}</td><td>${fmt(e.year)} <span class="muted">giờ</span>${e.year>200?' '+badge('Vượt 200h','red'):''}</td><td>${fmt(e.metrics.hours.remainingMonth)} giờ</td><td>${fmt(e.metrics.hours.remainingYear)} giờ</td><td>${fmt(e.metrics.hours.excessMonth)} giờ</td><td>${fmt(e.metrics.hours.excessYear)} giờ</td><td><button class="btn-link" data-action="employee-detail" data-id="${esc(e.id)}">Chi tiết ${icon('chevron')}</button></td></tr>`).join('')||'<tr><td class="empty" colspan="10">Không tìm thấy cán bộ phù hợp. Hãy thử mã hoặc tên khác.</td></tr>'}</tbody></table></div><div class="table-footer"><span>${list.length} / ${employees.length} cán bộ ${dataMode==='demo'?'giả lập':'đã nhập'}</span><span>${lookup?'Tổng OT cộng dồn mọi dự án':'Mỗi cán bộ có một mã duy nhất'}</span></div>`;}
function employeeToolbar(){return `<div class="toolbar"><div class="search-field">${icon('search')}<input id="employee-search" class="field" placeholder="Tìm mã cán bộ, tên hoặc đơn vị…" aria-label="Tìm kiếm cán bộ" value="${esc(state.search)}"></div><div class="toolbar-filters"><select class="field" data-filter="project" aria-label="Lọc dự án">${projectOptions()}</select><select class="field" data-filter="unit" aria-label="Lọc đơn vị"><option value="all">Tất cả đơn vị</option>${[...new Set(employees.map(e=>e.unit))].map(u=>`<option ${state.unit===u?'selected':''}>${u}</option>`).join('')}</select></div></div>`;}
function dataAvailability(){if(dataMode!=='imported')return '';const active=history.filter(h=>h.status==='active');const periods=[...new Set(active.map(h=>`${h.year}-${h.month}`))].sort((a,b)=>Number(b.split('-')[0])-Number(a.split('-')[0])||Number(b.split('-')[1])-Number(a.split('-')[1]));return `<div class="notice section-space"><span><strong>Kho đang có ${active.length} file đã lưu, ${entries.length} bản ghi OT.</strong> Đang xem tháng ${state.month||'tất cả'}/${state.year}, dự án ${esc(state.project)}.${periods.length?' Chọn kỳ đã lưu:':''} ${periods.slice(0,12).map(p=>{const [year,month]=p.split('-');return `<button class="btn btn-quiet" data-action="open-period" data-year="${year}" data-month="${month}">${month}/${year}</button>`;}).join('')}</span><button class="btn" data-action="latest-data">Xem dữ liệu mới nhất</button></div>`;}
function employeesView(lookup=false){const list=filterEmployees();return `${heading(lookup?'Tra cứu OT':'Danh sách nhân sự',lookup?'Tra cứu tổng giờ làm thêm của một cán bộ trên tất cả dự án.':'Một danh tính duy nhất. Một góc nhìn xuyên suốt các dự án.',periodFilter()+button('Xuất danh sách','download','export-csv'))}${demoNotice()}${dataAvailability()}${lookup?`<div class="mini-stats section-space"><article class="panel mini-stat"><p>Cán bộ theo bộ lọc</p><strong id="lookup-count">${list.length}</strong></article><article class="panel mini-stat"><p>OT tháng · mọi dự án</p><strong id="lookup-month">${fmt(list.reduce((a,e)=>a+e.month,0))} <small>giờ</small></strong></article><article class="panel mini-stat"><p>OT năm · mọi dự án</p><strong id="lookup-year">${fmt(list.reduce((a,e)=>a+e.year,0))} <small>giờ</small></strong></article></div>`:''}<section class="panel section-space">${employeeToolbar()}<div id="employee-results">${employeeTable(list,lookup)}</div></section><div class="coverage section-space">${icon('info')} Bộ lọc dự án chọn cán bộ có tham gia dự án trong tháng. Tổng OT tháng/năm vẫn cộng dồn trên mọi dự án.</div>`;}
function alertsView(){const totals=employeeTotals();const month=totals.filter(e=>e.month>40),year=totals.filter(e=>e.year>200),near=totals.filter(e=>e.month>=32&&e.month<=40);const conflicts=dayConflicts(metricRecords()).filter(c=>c.date.startsWith(`${state.year}-${String(state.month).padStart(2,'0')}`));const mode=state.alertTab;const list=mode==='month'?month:mode==='year'?year:near;return `${heading('Cảnh báo vượt giờ','Phát hiện sớm, chủ động cân đối. Cảnh báo không chặn upload.',periodFilter())}<div class="mini-stats">${[['Vượt 40 giờ / tháng',month.length],['Vượt 200 giờ / năm',year.length],['Gần hạn mức tháng',near.length]].map(([t,n])=>`<article class="panel mini-stat"><p>${t}</p><strong>${n} <small>cán bộ</small></strong></article>`).join('')}</div><div class="notice notice-warning">${icon('alert')}<span>Giới hạn nghiệp vụ: <strong>40 giờ/tháng và 200 giờ/năm</strong>, cộng dồn mọi dự án. Dữ liệu tổng tháng chưa đủ để kiểm tra khai trùng ngày giữa hai dự án.</span></div><section class="panel section-space"><div class="tabs" role="tablist" aria-label="Loại cảnh báo">${[['month','Vượt giờ tháng',month.length],['year','Vượt giờ năm',year.length],['near','Gần hạn mức',near.length],['days','Trùng ngày',conflicts.length]].map(([v,t,n])=>`<button class="tab ${mode===v?'active':''}" role="tab" aria-selected="${mode===v}" data-action="alert-tab" data-tab="${v}">${t} (${n})</button>`).join('')}</div>${mode==='days'?`<div class="table-wrap"><table><thead><tr><th>MÃ CÁN BỘ</th><th>NGÀY</th><th>DỰ ÁN</th><th>TRẠNG THÁI</th></tr></thead><tbody>${conflicts.map(c=>`<tr><td>${esc(c.employeeId)}</td><td>${esc(c.date)}</td><td>${esc(c.projects.join(', '))}</td><td>${badge('Cảnh báo · Giữ nguyên dữ liệu','orange')}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Không phát hiện ngày trùng trong các bản ghi chi tiết đã nhập.</td></tr>'}</tbody></table></div>`:`<div class="table-wrap"><table><thead><tr><th>CÁN BỘ</th><th>ĐƠN VỊ</th><th>${mode==='year'?'OT NĂM':'OT THÁNG'}</th><th>${mode==='near'?'CÒN LẠI':'VƯỢT HẠN MỨC'}</th><th>TRẠNG THÁI</th><th></th></tr></thead><tbody>${list.map(e=>`<tr><td>${person(e)}</td><td>${esc(e.unit)}</td><td><strong>${fmt(mode==='year'?e.year:e.month)} giờ</strong></td><td>${fmt(mode==='near'?40-e.month:mode==='year'?e.year-200:e.month-40)} giờ</td><td>${badge(mode==='near'?'Cần theo dõi':'Cần kiểm tra',mode==='year'?'red':'orange')}</td><td><button class="btn-link" data-action="employee-detail" data-id="${esc(e.id)}">Xem chi tiết ${icon('arrow')}</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Không có cảnh báo thuộc nhóm này trong kỳ đã chọn.</td></tr>'}</tbody></table></div>`}<div class="table-footer"><span>${mode==='days'?conflicts.length+' cảnh báo ngày':list.length+' cán bộ'} · ${dataMode==='demo'?'Dữ liệu giả lập':'Dữ liệu đã nhập'}</span><span>Đúng ngưỡng không được tính là vượt</span></div></section>`;}
function historyView(){const list=[...(dataMode==='demo'?state.previewImports:[]),...history].filter(h=>(state.project==='all'||h.projectId===state.project)&&normalize(h.filename).includes(normalize(state.search)));return `${heading('Lịch sử import','Mỗi thay đổi đều có dấu vết. Mỗi kỳ chỉ cộng dữ liệu có hiệu lực.',button('Upload chấm công','plus','go-upload',true))}${demoNotice()}${dataAvailability()}<section class="panel section-space"><div class="toolbar"><div class="search-field">${icon('search')}<input class="field" id="history-search" value="${esc(state.search)}" placeholder="Tìm tên file…" aria-label="Tìm tên file import"></div><div class="toolbar-filters"><select class="field" data-filter="project" aria-label="Lọc dự án lịch sử">${projectOptions()}</select></div></div><div id="history-results">${historyTable(list)}</div></section><div class="coverage section-space">${icon('info')} Thay thế toàn bộ kỳ sẽ vô hiệu hóa cả file gốc và các file bổ sung. Không xóa lịch sử phiên bản.</div>${dataMode==='imported'?auditPanel(storedSnapshot?.auditLogs||[]):''}`;}
function historyTable(list){return `<div class="table-wrap"><table><thead><tr><th>FILE CHẤM CÔNG</th><th>DỰ ÁN / KỲ</th><th>THAO TÁC</th><th>CÁN BỘ</th><th>THỜI ĐIỂM</th><th>TRẠNG THÁI</th><th></th></tr></thead><tbody>${list.map(h=>`<tr><td><div class="person"><span class="activity-symbol">${icon('file')}</span><div><div class="person-name">${esc(h.filename)}</div><div class="person-code">${esc(h.id)}</div></div></div></td><td>${esc(h.projectId)}<div class="person-code">Tháng ${h.month}/${h.year}</div></td><td>${h.type==='cancel'?'Đã hủy':h.type==='replace'?'Thay thế kỳ':h.type==='supplement'?'Bổ sung':'Nhập mới'}</td><td>${h.count}</td><td>${h.preview?'Vừa xong':new Intl.DateTimeFormat('vi-VN',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Bangkok'}).format(new Date(h.date))}</td><td>${badge(h.preview?'Chỉ mô phỏng':h.status==='active'?'Có hiệu lực':h.status==='cancelled'?'Đã hủy':'Đã thay thế',h.preview?'blue':h.status==='active'?'green':'neutral')}</td><td><button class="btn-link" data-action="import-detail" data-id="${esc(h.id)}">Chi tiết ${icon('chevron')}</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Không tìm thấy lịch sử phù hợp.</td></tr>'}</tbody></table></div><div class="table-footer"><span>${list.length} lượt import ${dataMode==='demo'?'minh họa':'đã lưu'}</span><span>Giữ lịch sử · Chống cộng trùng</span></div>`;}
function reportsView(){return renderLongReports({report:currentReport(state.report==='yearly'?0:state.month||1),filters:reportFilters(state.report==='yearly'?'yearly':'monthly'),heading,button,type:state.report});}

function backupView(){if(dataMode==='imported')return `${heading('Sao lưu dữ liệu đã nhập','Xuất toàn bộ lịch sử, phiên bản có hiệu lực và mapping đã lưu.')}${demoNotice()}<section class="panel section-space"><div class="panel-body"><h2>Bản sao lưu IndexedDB</h2><p class="muted small section-space">Bản sao lưu có thể chứa dữ liệu nhân sự. Giữ file ở nơi an toàn; không commit vào repository.</p><div class="section-space">${button('Xuất dữ liệu đã nhập','download','real-backup-export',true)+button('Kiểm tra toàn vẹn','shield','check-integrity')}</div><div class="hr"></div><div id="restore-area"></div><p class="muted small section-space">Bản JSON bao gồm 6 bảng nghiệp vụ, các kỳ, mapping và metadata. Trước khi khôi phục, dữ liệu hiện tại được tải thành một bản JSON riêng.</p></div></section>`;return `${heading('Sao lưu dữ liệu','Chủ động giữ một bản sao. An tâm hơn với dữ liệu của bạn.')}${demoNotice()}<div class="grid-two section-space"><section class="panel backup-card">${icon('download')}<h2>Xuất bản sao lưu demo</h2><p>Tải dữ liệu giả lập trong phiên trải nghiệm dưới dạng JSON. File có nhãn DEMO và không được ghi vào kho dữ liệu chính.</p><div class="backup-meta"><div><strong>${projects.length}</strong><span>Dự án mẫu</span></div><div><strong>${employees.length}</strong><span>Cán bộ mẫu</span></div><div><strong>${entries.length}</strong><span>Bản ghi OT mẫu</span></div></div>${button('Tải bản sao lưu DEMO','download','backup-export',true)}</section><section class="panel backup-card">${icon('upload')}<h2>Kiểm tra bản sao lưu</h2><p>Chọn bản JSON được xuất từ giao diện này để kiểm tra cấu trúc và xem thống kê. Chức năng này không khôi phục hoặc ghi bất kỳ dữ liệu nào.</p><input class="file-input" type="file" id="backup-file" accept=".json"><label class="dropzone" for="backup-file" style="display:block;margin-top:0"><span class="upload-symbol">${icon('file')}</span><h3><strong>Chọn file JSON giả lập</strong></h3><p>Chỉ xem trước · Tối đa 5 MB</p></label><div id="backup-result" role="status" class="small muted">Chưa chọn bản sao lưu.</div></section></div><section class="panel section-space"><div class="panel-body"><h2>Những điều cần biết về lưu trữ</h2><div class="rule-list">${[['database','Dữ liệu cục bộ theo trình duyệt','Khi triển khai IndexedDB, dữ liệu thuộc trình duyệt và origin website. Đổi máy hoặc xóa dữ liệu duyệt web có thể làm mất dữ liệu.'],['shield','Bản xem trước chưa ghi dữ liệu','Tất cả thay đổi trong giao diện này chỉ tồn tại trong bộ nhớ. Tải lại trang sẽ trở về dữ liệu mẫu ban đầu.'],['history','Sao lưu trước khi thay đổi lớn','Bản chính thức cần sao lưu trước khi khôi phục, nâng cấp dữ liệu hoặc thay thế nhiều kỳ.']].map(([i,t,p])=>`<div class="rule">${icon(i)}<div><strong>${t}</strong><p>${p}</p></div></div>`).join('')}</div></div></section>`;}
function render(){restoreUI.unmount();excelUI.unmount();renderShell();if(state.route==='upload'&&!demoUpload){excelUI.mount($('#main'));document.title='Import Excel · OT Workspace';return;}const views={dashboard,upload:uploadView,projects:projectsView,employees:()=>employeesView(false),lookup:()=>employeesView(true),alerts:alertsView,history:historyView,reports:reportsView,backup:backupView};$('#main').innerHTML=(views[state.route]||dashboard)();document.title=`${nav.find(n=>n[0]===state.route)?.[2]||'Tổng quan'} · OT Workspace`;bindDropzone();if(state.route==='backup'&&dataMode==='imported')restoreUI.mount($('#restore-area'));}
function route(){let next=location.hash.replace(/^#\//,'');if(next==='main')return;if(!nav.some(n=>n[0]===next))next='dashboard';if(next!==state.route){if(next==='upload')excelUI.reset();demoUpload=false;state.search='';state.unit='all';if(!['dashboard','reports'].includes(next)&&state.month===0)state.month=1;}state.route=next;if(next==='upload'&&dataMode==='demo')demoUpload=true;$('#sidebar').classList.remove('open');$('#sidebar-overlay').classList.remove('visible');render();window.scrollTo({top:0,behavior:'instant'});}
function employeeDetail(id){const e=employeeTotals().find(e=>e.id===id);if(!e)return;const rows=projects.map(p=>({p,rows:periodEntries().filter(r=>r.employeeId===id&&r.projectId===p.id)})).filter(r=>r.rows.length);showModal('Chi tiết giờ làm thêm',`<div class="person-detail"><span class="avatar ${e.color}">${esc(e.initials)}</span><div><h2>${esc(e.name)}</h2><p class="muted">${esc(e.id)} · ${esc(e.unit)}</p></div></div>${metricsMarkup(e.metrics,fmt)}<div class="table-wrap"><table><thead><tr><th>DỰ ÁN</th><th>NT</th><th>NN</th><th>TỔNG</th></tr></thead><tbody>${rows.map(({p,rows})=>`<tr><td>${p.id}</td><td>${fmt(rows.reduce((a,r)=>a+r.nt,0))}h</td><td>${fmt(rows.reduce((a,r)=>a+r.nn,0))}h</td><td>${fmt(sum(rows))}h</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Chưa có dữ liệu trong kỳ này.</td></tr>'}</tbody></table></div><h3 class="section-space">Lịch sử OT qua các năm</h3><div class="table-wrap history-scroll"><table><thead><tr><th>KỲ</th><th>DỰ ÁN</th><th>TÊN / ĐƠN VỊ LÚC IMPORT</th><th>OT</th><th>PHIÊN BẢN</th></tr></thead><tbody>${(dataMode==='imported'?storedSnapshot.otRecords:metricRecords()).filter(r=>r.employeeId===id).sort((a,b)=>b.year-a.year||b.month-a.month).map(r=>`<tr><td>${r.month}/${r.year}</td><td>${esc(r.projectId)}</td><td>${esc(r.name||e.name)}<div class="person-code">${esc(r.unit||'')}</div></td><td>${fmt(r.totalMinutes/60)}h</td><td>${badge(r.status==='archived'?'Đã thay thế':'Có hiệu lực',r.status==='archived'?'neutral':'green')}</td></tr>`).join('')}</tbody></table></div><div class="notice notice-warning section-space">${icon('info')}<span>${dataMode==='demo'?'Dữ liệu tổng tháng: chưa xác minh trùng ngày.':'Trùng ngày liên dự án chỉ được cảnh báo, không tự xóa hoặc loại khỏi tổng OT. Dữ liệu tổng hợp chưa đủ để kiểm tra trùng ngày.'}</span></div>`,(dataMode==='imported'?`<button class="btn" data-action="edit-employee" data-id="${esc(e.id)}">Chỉnh sửa cán bộ</button>`:'')+button('Đóng','','close-modal'));}
function projectForm(id,onCreated){const p=projects.find(p=>p.id===id);showModal(p?'Chỉnh sửa dự án':'Thêm dự án',`<form id="project-form"><div class="form-grid"><div class="form-group"><label for="project-code">Mã dự án *</label><input class="field" id="project-code" name="code" maxlength="12" pattern="[A-Za-z0-9_]+(?:-[A-Za-z0-9_]+)*" required value="${esc(p?.id||'')}" ${p?'readonly':''}><small>Chữ, số, dấu gạch ngang; tối đa 12 ký tự.</small></div><div class="form-group"><label for="project-status">Trạng thái</label><select class="field" id="project-status" name="status"><option value="active">Đang hoạt động</option><option value="inactive" ${p?.status==='inactive'?'selected':''}>Ngừng hoạt động</option></select></div><div class="form-group"><label for="project-name">Tên dự án *</label><input class="field" id="project-name" name="name" required maxlength="80" value="${esc(p?.name||'')}"></div><div class="form-group"><label for="project-manager">Phụ trách</label><input class="field" id="project-manager" name="manager" maxlength="60" value="${esc(p?.manager||(dataMode==='demo'?'Cán bộ Demo':''))}"></div></div><div class="form-group section-space"><label for="project-description">Mô tả</label><input class="field" id="project-description" name="description" maxlength="120" value="${esc(p?.description||'')}"></div><div class="notice section-space">${icon('info')}<span>${dataMode==='demo'?'Chỉ sử dụng tên giả lập. Thay đổi chỉ tồn tại trong phiên demo.':'Dự án được lưu vào Projects và mọi thay đổi được ghi AuditLogs.'}</span></div><div class="form-actions"><button class="btn" type="button" data-action="close-modal">Hủy</button><button class="btn btn-primary" type="submit">${icon('check')} Lưu dự án${dataMode==='demo'?' mẫu':''}</button></div></form>`);$('#project-form').addEventListener('submit',async event=>{event.preventDefault();const data=new FormData(event.target);const code=data.get('code').trim().toUpperCase(),name=data.get('name').trim();if(!code||!name)return toast('Vui lòng nhập mã và tên dự án.');if(!p&&projects.some(r=>r.id===code))return toast('Mã dự án đã tồn tại. Vui lòng chọn mã khác.');const record={id:code,name,description:data.get('description').trim(),manager:data.get('manager').trim()||'Chưa phân công',status:data.get('status'),color:p?.color||'green'};try{if(dataMode==='imported'){await (p?saveProject(record):createProject(record));await useImportedData();}else if(p)Object.assign(p,record);else projects.push(record);$('#modal').close();if(onCreated)onCreated(record.id);render();toast(dataMode==='demo'?'Đã lưu dự án trong bộ nhớ tạm của phiên demo.':'Đã lưu dự án và nhật ký thay đổi.');}catch(e){toast(e.message);}});}
function importDetail(id){const h=[...(dataMode==='demo'?state.previewImports:[]),...history].find(h=>h.id===id);if(!h)return;showModal('Chi tiết lần import',`<div class="file-summary">${icon('file')}<div><strong>${esc(h.filename)}</strong><p>${esc(h.id)}</p></div>${badge(h.preview?'Chỉ mô phỏng':h.status==='active'?'Có hiệu lực':h.status==='cancelled'?'Đã hủy':'Đã thay thế',h.preview?'blue':h.status==='active'?'green':'neutral')}</div><dl class="detail-list"><div><dt>Dự án</dt><dd>${esc(h.projectId)}</dd></div><div><dt>Kỳ chấm công</dt><dd>Tháng ${h.month}/${h.year}</dd></div><div><dt>Số cán bộ</dt><dd>${h.count}</dd></div><div><dt>Hình thức</dt><dd>${h.type==='cancel'?'Hủy lượt nhập':h.type==='replace'?'Thay thế toàn bộ kỳ':h.type==='supplement'?'Bổ sung':'Nhập mới'}</dd></div><div><dt>Ngày OT chi tiết</dt><dd>${dataMode==='demo'?'Chưa có dữ liệu':h.hasDaily?'Đã lưu theo từng cán bộ/ngày':'Chỉ có dữ liệu tổng hợp'}</dd></div></dl>${dataMode==='imported'?`<h3>Snapshot trước và sau</h3>${(h.events||[]).map(event=>`<div class="help-box"><strong>${esc(event.action)}</strong><p>Trước: ${event.before?`${event.before.employeeCount} cán bộ · ${fmt(event.before.totalMinutes/60)} giờ`:'Chưa có snapshot'}<br>Sau: ${event.after?`${event.after.employeeCount} cán bộ · ${fmt(event.after.totalMinutes/60)} giờ`:'Không thay đổi OT'}</p>${event.note?`<p>${esc(event.note)}</p>`:''}</div>`).join('')}`:''}<div class="notice">${icon('info')}<span>${dataMode==='demo'?'Đây là lịch sử minh họa. Các thao tác trong bản xem trước không thay đổi dữ liệu OT đang hiển thị.':'Phiên bản có hiệu lực được dùng để cộng dồn. Phiên bản đã thay thế vẫn được giữ trong lịch sử.'}</span></div>`,button('Đóng','','close-modal'));}

function employeeForm(id){const e=employees.find(e=>e.id===id);if(!e)return;showModal('Chỉnh sửa cán bộ',`<form id="employee-form"><div class="form-group"><label for="employee-code">Mã cán bộ (không đổi)</label><input class="field" id="employee-code" readonly value="${esc(e.id)}"></div><div class="form-group section-space"><label for="employee-name">Họ tên</label><input class="field" id="employee-name" required maxlength="120" value="${esc(e.name)}"></div><div class="form-group section-space"><label for="employee-unit">Đơn vị</label><input class="field" id="employee-unit" maxlength="120" value="${esc(e.unit)}"></div><p class="small muted section-space">Sửa hồ sơ không thay đổi tên/đơn vị gốc của các phiên bản import đã lưu.</p><div class="form-actions"><button type="button" class="btn" data-action="close-modal">Hủy</button><button type="submit" class="btn btn-primary">Lưu cán bộ</button></div></form>`);$('#employee-form').addEventListener('submit',async event=>{event.preventDefault();try{await saveEmployee({employeeId:e.id,name:$('#employee-name').value,unit:$('#employee-unit').value});await useImportedData();$('#modal').close();render();toast('Đã lưu hồ sơ và nhật ký thay đổi.');}catch(error){toast(error.message);}});}
function exportCSV(report=false){const value=currentReport(report&&state.report==='yearly'?0:state.month||1);let rows=value.rows;if(report&&state.report==='alerts')rows=rows.filter(r=>r.excessMonthMinutes>0);const yearly=report&&state.report==='yearly';const headers=['Mã cán bộ','Họ tên lúc import','Đơn vị lúc import','NT lọc (giờ)','NN lọc (giờ)','OT lọc (giờ)','Tổng mọi dự án trong kỳ','Tổng năm mọi dự án','Còn tháng','Còn năm','Vượt tháng','Vượt năm',...(yearly?Array.from({length:12},(_,i)=>`Tháng ${i+1}`):[])];const values=rows.map(r=>[r.employeeId,r.name,r.unit,r.ntMinutes/60,r.nnMinutes/60,r.totalMinutes/60,r.globalPeriodMinutes/60,r.yearMinutes/60,r.remainingMonthMinutes===null?'':r.remainingMonthMinutes/60,r.remainingYearMinutes/60,r.excessMonthMinutes===null?'':r.excessMonthMinutes/60,r.excessYearMinutes/60,...(yearly?r.months.map(m=>m.selectedMinutes/60):[])]);const cell=v=>`"${String(v).replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')}"`;download(`${dataMode==='demo'?'DEMO_OT':'OT'}_${report?state.report:'nhansu'}_${state.month}_${state.year}.csv`,'\ufeff'+[headers,...values].map(row=>row.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('Đã xuất dữ liệu theo bộ lọc; hạn mức cộng mọi dự án.');}

function captureUpload(){const p=$('#upload-project'),y=$('#upload-year');if(p)state.project=p.value;if(y)state.year=Number(y.value);state.importMode=document.querySelector('[name="import-mode"]:checked')?.value||state.importMode;}
function setFile(file){if(!file)return;if(!/\.(xlsx|xls)$/i.test(file.name))return toast('Vui lòng chọn file Excel .xlsx hoặc .xls.');if(file.size>10*1024*1024)return toast('File vượt giới hạn xem trước 10 MB.');captureUpload();state.file=null;state.filename=file.name;render();toast('Đã nhận tên file. Nội dung chưa được đọc; bước tiếp theo dùng dữ liệu mô phỏng.');}
function bindDropzone(){const drop=$('#dropzone');if(!drop)return;drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('dragging');});drop.addEventListener('dragleave',()=>drop.classList.remove('dragging'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('dragging');setFile(e.dataTransfer.files[0]);});}
async function checkBackup(file){if(!file)return;const target=$('#backup-result');if(file.size>5*1024*1024){target.textContent='File vượt giới hạn 5 MB.';return;}try{const data=JSON.parse(await file.text());if(data.format!=='ot-workspace-demo'||data.schemaVersion!==1||data.demo!==true)throw Error('Chỉ hỗ trợ bản sao lưu DEMO phiên bản 1.');for(const key of ['projects','employees','entries'])if(!Array.isArray(data[key]))throw Error('Bản sao lưu thiếu danh sách '+key+'.');if(data.projects.some(p=>typeof p.id!=='string'||typeof p.name!=='string')||data.employees.some(e=>typeof e.id!=='string'||typeof e.name!=='string'))throw Error('Thông tin dự án hoặc nhân sự không hợp lệ.');const employeeIds=new Set(data.employees.map(e=>e.id)),projectIds=new Set(data.projects.map(p=>p.id));if(employeeIds.size!==data.employees.length||projectIds.size!==data.projects.length)throw Error('Phát hiện mã định danh trùng.');if(data.entries.some(r=>!employeeIds.has(r.employeeId)||!projectIds.has(r.projectId)||!Number.isInteger(r.year)||!Number.isInteger(r.month)||r.month<1||r.month>12||![r.nt,r.nn].every(v=>typeof v==='number'&&Number.isFinite(v)&&v>=0)))throw Error('Bản ghi OT có giá trị hoặc liên kết không hợp lệ.');target.textContent=`Cấu trúc DEMO hợp lệ: ${data.projects.length} dự án, ${data.employees.length} cán bộ, ${data.entries.length} bản ghi. Chỉ kiểm tra; chưa khôi phục dữ liệu.`;}catch(error){target.textContent=`Không thể kiểm tra: ${error.message}`;}}

document.addEventListener('click',event=>{const actionNode=event.target.closest('[data-action]');if(!actionNode)return;const action=actionNode.dataset.action;switch(action){case 'toggle-menu':{const open=$('#sidebar').classList.toggle('open');$('#sidebar-overlay').classList.toggle('visible',open);actionNode.setAttribute('aria-expanded',String(open));break;}case 'latest-data':{(async()=>{try{await useImportedData({selectLatest:true});location.hash='/lookup';render();}catch(e){toast(e.message);}})();break;}case 'open-period':state.year=Number(actionNode.dataset.year);state.month=Number(actionNode.dataset.month);state.project='all';state.unit='all';state.search='';location.hash='/lookup';render();break;case 'go-upload':location.hash='/upload';break;case 'close-modal':$('#modal').close();break;case 'dismiss-notice':state.notice=false;render();break;case 'notifications':location.hash='/alerts';break;case 'employee-detail':employeeDetail(actionNode.dataset.id);break;case 'add-project':projectForm();break;case 'edit-project':projectForm(actionNode.dataset.id);break;case 'edit-employee':employeeForm(actionNode.dataset.id);break;case 'audit-detail':{const log=storedSnapshot?.auditLogs.find(a=>a.id===actionNode.dataset.id);if(log)showModal('Chi tiết nhật ký',`<pre class="audit-json">${esc(JSON.stringify(log,null,2))}</pre>`,button('Đóng','','close-modal'));break;}case 'alert-tab':state.alertTab=actionNode.dataset.tab;render();break;case 'import-detail':importDetail(actionNode.dataset.id);break;case 'select-report':state.report=actionNode.dataset.report;if(!state.month)state.month=1;render();break;case 'export-csv':exportCSV();break;case 'export-report':exportCSV(true);break;case 'export-excel':{const button=actionNode;button.disabled=true;const context={employees:structuredClone(employees),records:structuredClone(metricRecords()),projects:structuredClone(projects),year:state.year,month:state.month||1,report:state.report,projectId:state.project,demo:dataMode==='demo'};(async()=>{try{const {loadSheetJS,createOTWorkbook}=await import('../../src/reports/excel-export.mjs');const X=await loadSheetJS();const book=createOTWorkbook(context,X);download(`${context.demo?'DEMO_OT':'OT'}_${context.report}_${context.month}_${context.year}.xlsx`,X.write(book,{type:'array',bookType:'xlsx'}),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');toast('Đã xuất Excel: tổng hợp, chi tiết dự án và ngày OT.');}catch(error){toast(error.message);}finally{button.disabled=false;}})();break;}case 'check-integrity':{(async()=>{try{const {readFullBackup,validateBackup}=await import('./database.js');const result=await validateBackup(await readFullBackup());showModal('Kiểm tra toàn vẹn',`<p>Toàn bộ khóa, liên kết, OTDetails, giờ tính và snapshot hợp lệ.</p><div class="detail-list">${Object.entries(result.counts).map(([name,count])=>`<div><dt>${esc(name)}</dt><dd>${count}</dd></div>`).join('')}</div>`,button('Đóng','','close-modal'));}catch(e){toast(e.message);}})();break;}case 'real-backup-export':{(async()=>{try{const {readFullBackup}=await import('./database.js');download('OT_Workspace_backup.json',JSON.stringify(await readFullBackup(),null,2));toast('Đã xuất bản sao lưu dữ liệu đã nhập.');}catch(e){toast(e.message);}})();break;}case 'backup-export':download('DEMO_OT_Workspace_backup.json',JSON.stringify({format:'ot-workspace-demo',schemaVersion:1,demo:true,exportedAt:new Date().toISOString(),projects,employees,entries,history},null,2));toast('Đã tải bản sao lưu DEMO.');break;case 'clear-file':captureUpload();state.file=null;state.filename='';render();break;case 'use-demo':captureUpload();state.filename=`DEMO_${state.project}_T${state.month}_${state.year}.xlsx`;render();toast('Đã chọn bộ dữ liệu mô phỏng.');break;case 'upload-next':captureUpload();if(!state.filename)return toast('Hãy chọn file hoặc thử với dữ liệu giả lập.');state.uploadStep=2;render();break;case 'upload-review':state.month=Number($('#mapping-month').value);state.uploadStep=3;render();break;case 'upload-back':state.uploadStep=Math.max(1,state.uploadStep-1);render();break;case 'confirm-import':{if(!$('#confirm-year')?.checked)return toast('Vui lòng xác nhận kỳ chấm công trước khi tiếp tục.');if(state.importMode==='supplement')return;state.previewImports.unshift({id:`DEMO-${Date.now()}`,projectId:state.project,filename:state.filename,month:state.month,year:state.year,date:new Date().toISOString(),type:state.importMode,count:3,status:'preview',preview:true});state.uploadStep=1;state.filename='';location.hash='/history';toast('Đã thêm hoạt động mô phỏng. Không thay đổi hay lưu dữ liệu OT chính.');break;}}});
document.addEventListener('change',event=>{const target=event.target;if(target.id==='workspace-mode'){(async()=>{try{if(target.value==='imported')await useImportedData();else useDemoData();demoUpload=dataMode==='demo';render();}catch(e){toast('Không đọc được dữ liệu: '+e.message);render();}})();return;}if(target.dataset.filter){const key=target.dataset.filter;state[key]=['month','year'].includes(key)?Number(target.value):target.value;render();}if(target.id==='excel-file')setFile(target.files[0]);if(target.id==='backup-file')checkBackup(target.files[0]);});
document.addEventListener('input',event=>{if(event.target.id==='employee-search'){state.search=event.target.value;const list=filterEmployees();$('#employee-results').innerHTML=employeeTable(list,state.route==='lookup');if(state.route==='lookup'){$('#lookup-count').textContent=list.length;$('#lookup-month').innerHTML=`${fmt(list.reduce((a,e)=>a+e.month,0))} <small>giờ</small>`;$('#lookup-year').innerHTML=`${fmt(list.reduce((a,e)=>a+e.year,0))} <small>giờ</small>`;}}if(event.target.id==='history-search'){state.search=event.target.value;$('#history-results').innerHTML=historyTable([...(dataMode==='demo'?state.previewImports:[]),...history].filter(h=>(state.project==='all'||h.projectId===state.project)&&normalize(h.filename).includes(normalize(state.search))));}});
$('#sidebar-overlay').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#sidebar-overlay').classList.remove('visible');$('.mobile-menu')?.setAttribute('aria-expanded','false');});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){$('#sidebar').classList.remove('open');$('#sidebar-overlay').classList.remove('visible');$('.mobile-menu')?.setAttribute('aria-expanded','false');}});
let initialized=false;window.addEventListener('hashchange',()=>{if(initialized)route();});
(async()=>{try{await useImportedData({selectLatest:true});initialized=true;route();}catch(error){$('#main').innerHTML='<h1>Không mở được kho dữ liệu</h1><p></p>';$('#main p').textContent=error.message;}})();
